/**
 * Storno z detailu objednavky (2026).
 *
 * Stav nemenime v SQL: storno dela novy e-shop, ktery uvolni rezervace
 * ve skladu a u zaplacene objednavky spocita castku k vraceni.
 */
public function cancelAction()
{
    global $db;
    legacy_db();

    $id = post_param('id');
    $order = $db->one("SELECT * FROM orders WHERE id = '" . $id . "'");
    if (!is_post() || $order === null) {
        return $this->notFound('Objednávka ' . $id . ' neexistuje');
    }

    $reason = trim(post_param('reason'));
    if ($reason == '') {
        $reason = 'storno v administraci (' . auth_login_name() . ')';
    }

    try {
        $GLOBALS['LEGACY_ORDERING']->cancelOrder($id, $reason);
    } catch (\DomainException $e) {
        flash('Objednávku ve stavu „' . order_state_label($order['status']) . '“ nelze stornovat.', 'error');

        return $this->redirect(admin_url('order', array('id' => $id)));
    }

    $after = $db->one("SELECT refund_amount_in_cents, refund_currency FROM orders WHERE id = '" . $id . "'");
    $refund = (int) $after['refund_amount_in_cents'];
    audit_log('order', $id, 'storno', array('from' => $order['status'], 'reason' => $reason, 'refund' => $refund));
    cache_delete('dashboard_stats');

    $msg = 'Objednávka stornována, rezervace ve skladu uvolněny.';
    if ($refund > 0) {
        $msg .= ' Zákazníkovi vraťte ' . format_price($refund, $after['refund_currency']) . '.';
    }
    flash($msg);

    return $this->redirect(admin_url('order', array('id' => $id)));
}

